// GERADO por scripts/split-stage-info.mjs — não edite à mão o cabeçalho.
// Fichas de PERSONAGEM (por `id`) das cenas de 1chronicles. Vem por import() junto com
// o roteiro do livro: quem lê Rute não baixa os nomes de Crônicas.
import type { StageInfo } from "@/lib/rpgStageInfo";

export const CHARS: Record<string, StageInfo> = {
  ismael: { title: "Ismael", subtitle: "Filho de Abraão e Agar (Gn 16:11)", text: "\"Chamarás o seu nome Ismael; porquanto o Senhor ouviu a tua aflição\" (Gn 16:11) — o nome quer dizer \"Deus ouve\". Foi anunciado como \"homem feroz\", cuja mão seria contra todos e a de todos contra ele (Gn 16:12); cresceu no deserto e tornou-se flecheiro (Gn 21:20). Por amor a Abraão, Deus o abençoou e fez dele uma grande nação de \"doze príncipes\" (Gn 17:20; 25:16); viveu 137 anos (Gn 25:17)." },
  juda: { title: "Judá", subtitle: "4º filho de Lia (Gn 29:35)", text: "Quarto filho de Lia: \"Esta vez louvarei ao Senhor\" — e o chamou Judá, \"louvor\" (Gn 29:35). Propôs vender José aos ismaelitas (Gn 37:26-27), mas depois ofereceu-se como fiador de Benjamim diante do irmão que não reconhecia (Gn 44:33). Sobre ele repousou a promessa maior: \"O cetro não se arredará de Judá... até que venha Siló\" (Gn 49:10) — a linhagem do Messias." },
  tamar: { title: "Tamar", subtitle: "Nora de Judá, mãe de Perez (Gn 38)", text: "Casada com Er e depois com Onã, os dois primeiros filhos de Judá, ficou viúva sem filhos quando ambos morreram (Gn 38:6-10). Negado o direito de gerar descendência, disfarçou-se e enganou o próprio sogro para que a promessa não se perdesse — e Judá reconheceu: \"Mais justa é ela do que eu\" (Gn 38:26). Deu à luz os gêmeos Perez e Zerá (Gn 38:29-30), e por Perez entrou na genealogia do Messias (Mt 1:3)." },
  amaleque: { title: "Amaleque", subtitle: "Filho de Elifaz, pai dos amalequitas (Gn 36:12)", text: "Neto de Esaú, nascido de Elifaz e da concubina Timna (Gn 36:12). Dele saiu o povo de Amaleque, o primeiro a atacar Israel na saída do Egito, ferindo os cansados na retaguarda (Êx 17:8-16; Dt 25:17-19). Por isso Deus jurou \"guerra contra Amaleque de geração em geração\" — de um ramo da casa de Esaú brotou um dos mais antigos inimigos do povo da aliança." },
  naassom: { title: "Naassom, filho de Aminadabe", subtitle: "Príncipe de Judá (Nm 1:7)", text: "Cabeça da maior das tribos — setenta e quatro mil e seiscentos homens (Nm 1:26-27) — e o primeiro a mover-se: Judá acampa e parte à frente, ao oriente (Nm 2:3; 10:14). Foi ele quem abriu os doze dias da dedicação, oferecendo no primeiro dia (Nm 7:12-17). Cunhado de Arão (Êx 6:23), está na linhagem que desce até Boaz, Davi e o Cristo (Rt 4:20; Mt 1:4): o cetro que Jacó prometera a Judá já vai adiante do arraial." },
  elisama: { title: "Elisama, filho de Amiúde", subtitle: "Príncipe de Efraim (Nm 1:10)", text: "Cabeça de Efraim, o filho mais novo de José a quem Jacó pôs a mão direita e a bênção maior (Gn 48:14,19). Efraim leva a bandeira do ocidente e marcha em terceiro lugar (Nm 2:18; 10:22). Oferece no sétimo dia da consagração (Nm 7:48-53). Da sua descendência sairá Josué, filho de Num, que introduzirá Israel na terra (1Cr 7:26-27)." },
  calebe: { title: "Calebe, filho de Jefoné", subtitle: "O espia fiel, herdeiro de Hebrom (Js 14:6)", text: "O quenezeu que, com Josué, trouxe bom relato da terra e creu contra a incredulidade dos dez: \"subamos animosamente... porque bem poderemos com ela\" (Nm 13:30). Por seguir \"integralmente\" ao Senhor, foi dos únicos daquela geração a entrar (Nm 14:24). Aos 85 anos, com a mesma fé de 45 anos antes, reivindicou o monte dos anaquins: \"dá-me este monte de que o Senhor falou\" (Js 14:12), e tomou Hebrom. Modelo de quem persevera na promessa até vê-la cumprida." },
  acsa: { title: "Acsa, filha de Calebe", subtitle: "A que pediu as fontes de água (Js 15:16)", text: "Dada por esposa a Otniel, que tomou Quiriate-Sefer, pediu ousadamente ao pai mais do que o campo do Neguebe: \"dá-me também fontes de águas\" — e Calebe lhe deu as fontes superiores e as inferiores (Js 15:19). Sabendo que a terra seca precisa de água viva, buscou a bênção completa; imagem de quem não se contenta com a herança pela metade, mas pede as fontes que a fazem frutificar." },
  otniel: { title: "Otniel, filho de Quenaz", subtitle: "O que tomou Quiriate-Sefer, primeiro juiz (Js 15:17)", text: "Parente de Calebe, conquistou Debir (Quiriate-Sefer) e por isso recebeu Acsa por mulher (Js 15:16-17). Mais tarde, quando Israel serviu a um rei da Mesopotâmia, \"o Senhor suscitou um libertador... a Otniel\", sobre quem veio o Espírito do Senhor, e a terra teve quarenta anos de descanso (Jz 3:9-11) — o primeiro dos juízes de Israel." },
  boaz: { title: "Boaz", subtitle: "O remidor, homem valente e rico (Rt 2:1)", text: "Parente de Elimeleque em Belém, saudava os segadores com \"o Senhor seja convosco\" e mandou que deixassem punhados de propósito para a estrangeira (Rt 2:4,16). Na eira, ouviu o pedido de Rute — \"estende pois tua capa sobre a tua serva, porque tu és o remidor\" — e prometeu resolvê-lo pela lei, sem pressa nem escândalo (Rt 3:9-13). À porta da cidade resgatou a herança e tomou Rute por mulher diante dos anciãos. Nele se vê a figura do Redentor que paga o preço e traz o excluído para dentro da família (Lv 25:25; Ef 1:7)." },
  elcana: { title: "Elcana", subtitle: "O pai de Samuel, levita de Ramataim-Zofim (1Sm 1:1)", text: "Efrateu da montanha de Efraim, subia \"de ano em ano\" a Siló para adorar e sacrificar ao SENHOR dos Exércitos (1Sm 1:3) — fidelidade rara num tempo em que \"cada um fazia o que parecia reto aos seus olhos\". Tinha duas mulheres, e a casa dividida entre a amada estéril e a fecunda que a provocava era ferida antiga em Israel (cf. Gn 29–30). A Ana dava \"uma parte excelente\", e a consolava com ternura desajeitada: \"não te sou eu melhor do que dez filhos?\" (1Sm 1:8). Quando ela fez o voto, ele não o desfez — como a lei lhe permitiria (Nm 30:6-8) —, mas disse: \"faze o que bem te parecer... confirme o Senhor a sua palavra\" (1Sm 1:23). Genealogia levítica confirmada em 1Cr 6:27,34." },
  samuel: { title: "Samuel", subtitle: "O último juiz, profeta e ungidor de reis (1Sm 3:20; 7:15)", text: "\"Todo o Israel, desde Dã até Berseba, conheceu que Samuel estava confirmado por profeta do Senhor\" (1Sm 3:20). Fez o povo tirar os deuses estranhos, reuniu-o em Mizpá e o levou a vencer os filisteus pela oração, e levantou a pedra EBEN-EZER: \"até aqui nos ajudou o Senhor\" (1Sm 7:12). Julgou Israel todos os dias da sua vida em circuito por Betel, Gilgal e Mizpá, com casa em Ramá (1Sm 7:15-17). Foi a dobradiça entre os juízes e a monarquia: ungiu Saul e depois Davi, e nunca se calou diante de nenhum dos dois — \"eis que o obedecer é melhor do que o sacrificar\" (1Sm 15:22). Quando morreu, \"todo o Israel se ajuntou, e o prantearam\" (1Sm 25:1). Hebreus 11:32 o conta entre os heróis da fé, e Jeremias 15:1 o põe ao lado de Moisés como intercessor." },
  saul: { title: "Saul", subtitle: "O primeiro rei de Israel (1Sm 9–31)", text: "Benjamita, filho de Quis, \"moço e tão bem parecido... desde os ombros para cima mais alto do que todo o povo\" (1Sm 9:2) — o rei que Israel pediu para ser \"como todas as nações\". Começou com humildade real: escondeu-se entre a bagagem no dia da proclamação (1Sm 10:22) e poupou os que o desprezaram (1Sm 11:13). Mas a coroa o corroeu: sacrificou em Gilgal sem esperar Samuel (1Sm 13:9-14), poupou Agague e o melhor do gado contra a ordem do SENHOR (1Sm 15), e ouviu a sentença \"rejeitou-te a ti, para que não sejas rei\". A partir dali, \"o Espírito do Senhor se retirou de Saul, e o atormentava um espírito mau\" (1Sm 16:14): perseguiu Davi por montes e desertos, mandou matar os oitenta e cinco sacerdotes de Nobe (1Sm 22:18-19), consultou a mulher de En-Dor e caiu sobre a própria espada em Gilboa (1Sm 31:4). Davi, a quem ele caçou, o chorou: \"como caíram os valentes!\" (2Sm 1:19)." },
  jonatas: { title: "Jônatas", subtitle: "Filho de Saul, o amigo de Davi (1Sm 13–31)", text: "Guerreiro de fé ousada: com o pajem apenas, subiu de gatinhas pelos penhascos de Bozez e Sené contra a guarnição filisteia, dizendo \"para com o Senhor nenhum impedimento há de livrar com muitos ou com poucos\" (1Sm 14:6). Provou o mel na ponta da vara sem saber do juramento do pai, e o povo o resgatou da morte (1Sm 14:27,45). Amou Davi \"como à sua própria alma\", despiu-se da própria capa, espada, arco e cinto para vesti-lo (1Sm 18:1-4) e fez com ele aliança diante do SENHOR — sabendo que estava entregando o trono que lhe caberia: \"tu reinarás sobre Israel, e eu serei o segundo depois de ti\" (1Sm 23:17). Defendeu-o do pai arriscando a própria vida sob a lança (1Sm 19:4; 20:33). Morreu ao lado de Saul em Gilboa, e Davi o pranteou: \"a tua amizade me era mais maravilhosa do que o amor de mulheres\" (2Sm 1:26)." },
  jesse: { title: "Jessé", subtitle: "O belemita, pai de Davi (1Sm 16:1)", text: "Neto de Boaz e Rute (Rt 4:17,22), criador de gado em Belém de Judá e pai de oito filhos. Quando Samuel veio com a bezerra do sacrifício, apresentou sete deles e não se lembrou de mandar chamar o caçula, que estava com as ovelhas — e o profeta teve de dizer: \"não nos assentaremos até que ele venha aqui\" (1Sm 16:11). Foi então que Deus deu a regra: \"o homem vê o que está diante dos olhos, porém o Senhor olha para o coração\" (1Sm 16:7). O seu nome ficou como o do tronco messiânico: \"sairá um rebento do tronco de Jessé\" (Is 11:1), e assim Cristo é \"a raiz e a geração de Davi\" (Ap 22:16)." },
  "eliabe-irmao-de-davi": { title: "Eliabe", subtitle: "O irmão mais velho de Davi (1Sm 16:6; 17:28)", text: "Primogênito de Jessé, de porte tão imponente que Samuel se enganou: \"certamente está perante o Senhor o seu ungido\" — e ouviu a correção que resume o capítulo: \"não atentes para a sua aparência, nem para a altura da sua estatura\" (1Sm 16:6-7). No vale do carvalho, ao ouvir o irmão pequeno perguntar por Golias, acendeu-se em ira contra ele: \"eu conheço a tua presunção e a maldade do teu coração; desceste apenas para ver a peleja\" (1Sm 17:28). Acusou Davi exatamente do que ele não estava fazendo. O gigante, naquele dia, não estava só do lado filisteu: estava também na voz do irmão." },
  davi: { title: "Davi", subtitle: "O pastor de Belém, ungido rei (1Sm 16–31)", text: "O oitavo e menor filho de Jessé, apascentando ovelhas quando Samuel derramou sobre ele o azeite no meio dos irmãos — \"e desde aquele dia em diante o Espírito do Senhor se apoderou de Davi\" (1Sm 16:13). Matou o leão e o urso do rebanho antes de derrubar Golias com uma funda, em nome do \"Senhor dos Exércitos\" (1Sm 17:45). Caçado dez anos pelo rei que servira, por duas vezes teve Saul na mão e não a estendeu contra \"o ungido do Senhor\" (1Sm 24:6). Homem \"segundo o coração de Deus\" (1Sm 13:14), e o rei de cuja casa veio o trono eterno (2Sm 7:16; Mt 1:1)." },
  mical: { title: "Mical", subtitle: "A filha mais nova de Saul, mulher de Davi (1Sm 18:20)", text: "\"Mical, filha de Saul, o amava\" (1Sm 18:20) — e o pai usou esse amor como armadilha, exigindo por dote cem prepúcios de filisteus na esperança de que Davi caísse pela mão do inimigo (1Sm 18:25). Quando Saul mandou vigiar a casa para matá-lo pela manhã, foi ela quem o desceu por uma janela e pôs no leito o ídolo dos TERAFINS com uma pele de cabra à cabeceira, ganhando a noite inteira de vantagem (1Sm 19:12-16). Ao pai mentiu para salvar o marido. Depois foi dada a outro homem, Paltiel, e mais tarde reclamada por Davi (1Sm 25:44; 2Sm 3:14-16). A história dos dois termina fria: ao vê-lo dançando diante da arca, \"o desprezou no seu coração\" (2Sm 6:16)." },
  abiatar: { title: "Abiatar", subtitle: "O único sacerdote que escapou de Nobe (1Sm 22:20)", text: "Filho de Aimeleque, escapou do massacre e fugiu para Davi, que assumiu a culpa diante dele: \"eu dei ocasião à morte de todas as almas da casa de teu pai. Fica comigo, não temas... estarás em segurança comigo\" (1Sm 22:22-23). Trouxe consigo o ÉFODE, e por ele Davi passou a consultar o SENHOR nas horas decisivas — em Queila (1Sm 23:9-12) e em Ziclague (1Sm 30:7-8). Foi sacerdote durante todo o reinado de Davi, carregou a arca e chorou com ele na fuga de Absalão; mas apoiou Adonias na sucessão e foi deposto por Salomão, \"para que se cumprisse a palavra do Senhor, que tinha dito sobre a casa de Eli em Siló\" (1Rs 2:27)." },
  abisai: { title: "Abisai", subtitle: "Filho de Zeruia, sobrinho de Davi (1Sm 26:6)", text: "Irmão de Joabe e de Asael, e o único que se ofereceu para descer com Davi ao arraial adormecido em Haquila: \"eu descerei contigo\" (1Sm 26:6). Achando Saul dormindo com a lança fincada à cabeceira, pediu o golpe único: \"deixa-me, pois, agora ferí-lo com a lança, até ao chão, uma só vez; e não o ferirei segunda\" (1Sm 26:8). Davi o conteve com a regra que o governava: \"quem estenderá a mão contra o ungido do Senhor e ficará inculpável?\" (1Sm 26:9). Abisai é o guerreiro leal e sempre pronto demais — o mesmo que quereria cortar a cabeça de Simei (2Sm 16:9) e que depois salvaria a vida de Davi na peleja contra o gigante Isbi-Benobe (2Sm 21:17)." },
  joabe: { title: "Joabe", subtitle: "Filho de Zeruia, o futuro capitão de Davi", text: "Sobrinho de Davi e irmão de Abisai e Asael, aparece já no bando do deserto e se tornaria o comandante do exército durante quase todo o reinado (2Sm 8:16). Soldado de altíssima competência e de consciência curta: matou Abner à traição em Hebrom (2Sm 3:27), executou a ordem que pôs Urias na linha de frente (2Sm 11:16-17) e matou Absalão contra a ordem expressa do rei (2Sm 18:14). Sabia, porém, dizer a Davi o que ninguém dizia (2Sm 19:5-7). Foi finalmente alcançado pela justiça que adiara, agarrado às pontas do altar (1Rs 2:28-34) — figura da lealdade sem temor de Deus." },
  urias: { title: "Urias, o heteu", subtitle: "Um dos valentes de Davi, marido de Bate-Seba (2Sm 23:39)", text: "Estrangeiro — heteu, de um povo cananeu — e ainda assim inscrito na lista de honra do reino, o último nome dos trinta e sete valentes de Davi (23:39). Chamado da frente de batalha para encobrir o adultério do rei, recusou-se a descer à própria casa: \"A arca, e Israel, e Judá ficaram em tendas; e Joabe, meu senhor, e os servos de meu senhor estão acampados no campo; e hei de eu entrar na minha casa, para comer e beber, e para me deitar com minha mulher?\" (11:11). Dormiu à porta da casa real com os servos; embebedado de propósito, dormiu à porta outra vez — sóbrio ou bêbado, mais fiel do que o ungido. Levou nas próprias mãos a carta que o condenava: \"Ponde a Urias na frente da maior força da peleja; e retirai-vos de detrás dele, para que seja ferido e morra\" (11:15). Morreu junto ao muro de Rabá, e a notícia chegou a Jerusalém escondida no meio de uma lista de baixas. Foi por causa dele que Natã pronunciou a sentença — \"não se apartará a espada jamais da tua casa\" (12:10) — e é o nome dele, não o dela, que Mateus preservou na genealogia do Messias (Mt 1:6)." },
  absalao: { title: "Absalão", subtitle: "Terceiro filho de Davi, o príncipe que roubou o reino (2Sm 13–18)", text: "Filho de Maaca, filha de Talmai, rei de Gesur (3:3): \"Não havia, porém, em todo o Israel homem tão belo e tão aprazível como Absalão; desde a planta do pé até à cabeça não havia nele defeito algum\" (14:25), e o cabelo que tosquiava uma vez por ano pesava duzentos siclos. Depois da violência contra Tamar, \"não falou com Amnom, nem mal nem bem\" (13:22) por dois anos inteiros, e então o mandou matar na tosquia de Baal-Hazor, alegre do vinho. Fugiu três anos para Gesur, voltou pela mão de Joabe e passou mais dois anos em Jerusalém sem ver a face do pai; para ser recebido, tocou fogo na cevada do próprio Joabe (14:28-31). Depois pôs-se todas as manhãs à beira do caminho da porta, ouvindo as demandas que o rei não ouvia e beijando quem se inclinava: \"assim furtava Absalão o coração dos homens de Israel\" (15:6). Proclamado em Hebrom, entrou na cidade abandonada e possuiu as concubinas do pai numa tenda no terraço, cumprindo ao sol a palavra de Natã (12:11-12; 16:22). No bosque de Efraim a cabeça se prendeu nos ramos de um grande carvalho e ele ficou \"pendurado entre o céu e a terra\" até os três dardos de Joabe (18:9,14); e do rei que ele quis destronar veio o pranto: \"Meu filho Absalão, meu filho, meu filho\" (18:33)." },
  asael: { title: "Asael", subtitle: "Filho de Zeruia, irmão de Joabe e Abisai (2Sm 2:18)", text: "Sobrinho de Davi e um dos trinta valentes (23:24), conhecido por uma coisa só: \"Asael era ligeiro de pés, como as gazelas do campo\" (2:18). No dia da peleja junto ao tanque de Gibeom escolheu a presa maior e perseguiu o velho capitão do norte: \"não se desviou de detrás de Abner, nem para a direita nem para a esquerda\" (2:19). Duas vezes Abner lhe pediu que largasse a caçada — \"por que hei de eu ferir-te e dar contigo em terra? E como levantaria eu o meu rosto diante de Joabe, teu irmão?\" (2:22) —, e duas vezes ele não quis. Morreu com a ponta da lança pela quinta costela, e \"todos os que chegavam ao lugar onde Asael caiu e morreu, paravam\" (2:23). Foi sepultado em Belém, na sepultura de seu pai (2:32). A velocidade lhe custou a vida, e o seu sangue virou o pretexto com que Joabe assassinou Abner à traição em Hebrom (3:27) — uma morte de rapaz que envenenou o reinado inteiro." },
  aitofel: { title: "Aitofel", subtitle: "O gilonita, conselheiro de Davi passado a Absalão (2Sm 15:12)", text: "Conselheiro do rei, com uma autoridade quase oracular: \"era o conselho de Aitofel, que aconselhava naqueles dias, como se a palavra de Deus se consultara\" (16:23). Absalão o mandou buscar em Giló, e foi a sua adesão que fez a conjuração ganhar corpo (15:12) — por isso Davi, fugindo descalço, não pediu exércitos, pediu isto: \"Ó Senhor, peço-te que torne em loucura o conselho de Aitofel\" (15:31). Aconselhou o terraço com as concubinas e depois o golpe frio e certeiro: doze mil homens naquela mesma noite, espantar o povo e \"então ferirei somente o rei\" (17:1-3). O plano era bom, e foi por ser bom que Deus o quebrou: Husai falou depois dele, \"porém assim o Senhor o ordenara, para aniquilar o bom conselho de Aitofel, para que o Senhor trouxesse o mal sobre Absalão\" (17:14). Sabendo-se derrotado, \"albardou o jumento, e levantou-se, e foi para sua casa e para a sua cidade, e deu ordem à sua casa, e se enforcou e morreu\" (17:23) — calculista até no suicídio, pôs os papéis em ordem antes de se matar. Era pai daquele Eliã que estava entre os valentes (23:34) e, por ele, avô de Bate-Seba (11:3); e é o amigo de mesa que levanta o calcanhar contra o rei (Sl 41:9), a figura que Jesus aplicaria a Judas na última ceia (Jo 13:18)." },
  husai: { title: "Husai", subtitle: "O arquita, o amigo do rei (2Sm 15:32-37)", text: "Encontrou Davi no cume do monte das Oliveiras \"com a roupa rasgada e terra sobre a cabeça\" (15:32), pronto a subir descalço com ele. O rei lhe deu uma missão pior que o exílio: voltar, fingir-se do outro lado — \"dissipar-me-ás então o conselho de Aitofel\" (15:34). Entrou em Jerusalém gritando \"Viva o rei, viva o rei!\" a quem não era rei, e aguentou na cara a suspeita de Absalão: \"É esta a tua beneficência para com o teu amigo?\" (16:16-17). Chamado a opinar, não atacou de frente o plano de Aitofel — pintou Davi e seus homens \"como a ursa no campo, roubada dos cachorros\" e ofereceu ao vaidoso o que ele queria ouvir: todo o Israel reunido \"em multidão como a areia do mar\", e o próprio Absalão à frente (17:8,11). Ganhou uma noite, e a noite ganhou a guerra; e o texto credita a vitória a quem devia: \"assim o Senhor o ordenara, para aniquilar o bom conselho de Aitofel\" (17:14). Mandou o aviso a Zadoque e Abiatar, e pelos pés de dois moços o rei passou o Jordão antes do amanhecer (17:15-22). A Bíblia lhe dá um título só, e é cargo e é verdade ao mesmo tempo: \"Husai, pois, amigo de Davi\" (15:37)." },
  amasa: { title: "Amasa", subtitle: "Primo de Davi, capitão de Absalão e depois do rei (2Sm 17:25)", text: "Filho de Itra e de Abigail, irmã de Zeruia — portanto sobrinho de Davi e primo de Joabe, do mesmo sangue dos dois lados da guerra (17:25). Absalão o \"constituiu a Amasa em lugar de Joabe sobre o arraial\", e ele comandou o exército rebelde derrotado no bosque de Efraim. Vencido, foi perdoado e promovido: para se livrar de Joabe, que matara Absalão contra a sua ordem, Davi entregou a este primo o comando do exército. Convocado a reunir Judá em três dias, \"demorou-se além do tempo que lhe tinha sido designado\" (20:5), e a demora abriu a porta ao homem que ele substituíra. Junto à pedra grande de Gibeom, Joabe o saudou como irmão: \"Vai bem, meu irmão? E Joabe, com a mão direita, pegou da barba de Amasa, para o beijar\" — e com a outra o feriu pela quinta costela, sem precisar de segundo golpe (20:9-10). Ficou \"envolto no seu sangue no meio do caminho\" até que o arrastassem para o campo e o cobrissem com um manto, porque todo o povo que passava parava para olhar (20:12). Foi um dos dois homens de quem Joabe \"em paz derramou o sangue de guerra\", e que Davi, morrendo, mandou Salomão cobrar de Joabe (1Rs 2:5)." },
  zadoque: { title: "Zadoque", subtitle: "O sacerdote, filho de Aitube (2Sm 8:17; 15:24-29)", text: "Descendente de Eleazar, filho de Arão, serviu ao lado de Abiatar durante todo o reinado de Davi (8:17). Na noite da fuga saiu de Jerusalém com todos os levitas e a arca da aliança, e o rei o mandou de volta com ela: \"Torna a levar a arca de Deus à cidade; que, se achar graça nos olhos do Senhor, ele me tornará a trazer para lá e me deixará ver a ela e a sua habitação\" (15:25) — Davi recusou usar a arca como amuleto, como Israel fizera em Ebenézer. Ficou dentro da cidade ocupada como os olhos e os ouvidos do rei, mandando por Aimaás e Jônatas os avisos que salvaram o exército inteiro (15:35-36; 17:15-21). Na volta, trabalhou para que Judá fosse o primeiro a buscar o rei (19:11). Foi ele quem ungiu Salomão em Giom, tomando \"o chifre de azeite do tabernáculo\" (1Rs 1:39). E quando Abiatar caiu por apoiar Adonias, \"a Zadoque, o sacerdote, pôs o rei em lugar de Abiatar\" (1Rs 2:35): dele veio a casa sacerdotal que substituiu a de Eli, e são os \"filhos de Zadoque\" que Ezequiel guarda para o serviço do santuário na visão do templo (Ez 44:15)." },
  hadadezer: { title: "Hadadezer", subtitle: "Filho de Reobe, rei de Zobá (2Sm 8:3)", text: "Rei arameu de Zobá, a maior potência da Síria no seu tempo, ferido por Davi \"quando ele ia recuperar o seu domínio sobre o rio Eufrates\" (8:3). Perdeu numa só campanha mil carros, setecentos cavaleiros e vinte mil homens de pé; e Davi jarretou todos os cavalos dos carros, reservando apenas cem (8:4) — Israel não quis a cavalaria das nações, obedecendo à lei do rei, que mandava que o rei \"não multiplicará para si cavalos\" (Dt 17:16). Os sírios de Damasco vieram socorrê-lo e caíram vinte e dois mil (8:5). Os escudos de ouro dos seus servos e o muito bronze de Betá e Berotai foram levados a Jerusalém e consagrados ao SENHOR (8:7-8,11). Ainda tentou refazer-se uma segunda vez, chamando os sírios do outro lado do rio sob o comando de Sobaque, e perdeu tudo em Helã (10:16-18). No fim, \"todos os reis, servos de Hadadezer, que foram feridos diante de Israel, fizeram paz com Israel, e o serviram\" (10:19) — e o bronze do inimigo virou material do culto do Deus vivo." },
  hirao: { title: "Hirão, rei de Tiro", subtitle: "O aliado fenício de Davi e de Salomão (2Sm 5:11; 1Rs 5)", text: "Rei da cidade portuária de Tiro, foi o primeiro soberano estrangeiro a reconhecer o reinado de Davi sobre todo o Israel: \"enviou mensageiros a Davi, e madeira de cedro, e carpinteiros, e pedreiros que edificaram a Davi uma casa\" (2Sm 5:11) — e foi diante desse palácio novo que Davi entendeu que o SENHOR exaltara o seu reino \"por amor do seu povo\" (2Sm 5:12). A amizade atravessou uma geração: \"Hirão sempre tinha amado a Davi\", e por isso ele mandou os seus servos a Salomão assim que soube da unção (1Rs 5:1). O acordo do templo é dele: os sidônios, que sabiam cortar madeira como ninguém, derrubaram os CEDROS DO LÍBANO, que desceram em jangadas pelo mar, em troca de trigo e azeite batido para a sua casa, ano após ano (1Rs 5:6-11). Enviou também o artífice de cobre que fundiu as duas colunas e o mar (1Rs 7:13-14), e os seus marinheiros levaram a frota de Salomão a Ofir (1Rs 9:27). Nem tudo foi harmonia: as vinte cidades da Galileia que recebeu em pagamento não lhe agradaram, e ele perguntou \"Que cidades são estas que me deste, irmão meu?\" — o lugar ficou chamado \"Terra de Cabul, até hoje\" (1Rs 9:13). A casa do SENHOR foi levantada com madeira estrangeira e mãos estrangeiras — sinal antigo de que aquele Nome atrairia gente de \"terra remota\" (1Rs 8:41)." },
  "obede-edom": { title: "Obede-Edom", subtitle: "O giteu em cuja casa a arca ficou três meses (2Sm 6:10-12)", text: "Depois da morte de Uzá, Davi não teve coragem de recolher a arca à cidade e a desviou para a casa deste homem, chamado \"o giteu\" — provavelmente de Gate-Rimom, cidade dada aos levitas (6:10). O que para o rei era risco, para ele foi bênção: \"ficou a arca do Senhor em casa de Obede-Edom, o giteu, três meses; e abençoou o Senhor a Obede-Edom, e a toda a sua casa\" (6:11). Foi a notícia daquela casa próspera que devolveu a coragem a Davi: \"Abençoou o Senhor a casa de Obede-Edom, e tudo quanto tem, por causa da arca de Deus; foi pois Davi, e trouxe a arca de Deus para cima... com alegria\" (6:12). A mesma arca que feriu Uzá abençoou Obede-Edom: não mudou a arca, mudou o modo de se chegar a ela. E ele não voltou à vida de antes — as Crônicas o registram entre os porteiros da arca em Jerusalém (1Cr 15:24) e pai de oito filhos, com a explicação em quatro palavras: \"porque Deus o tinha abençoado\" (1Cr 26:5). Hospedou a presença de Deus por um trimestre e passou o resto da vida servindo à porta dela." },
  "salomao-menino": { title: "Salomão (Jedidias)", subtitle: "O menino a quem o SENHOR mandou chamar Jedidias (2Sm 12:24-25)", text: "Nasceu do consolo, não do escândalo: morto o primeiro filho, \"consolou Davi a Bate-Seba, sua mulher, e entrou a ela... e ela deu à luz um filho, e deu-lhe o nome de Salomão\" (12:24) — nome que traz dentro o shalom, a paz que aquela casa tinha perdido. E então vem a frase mais curta e mais espantosa do capítulo: \"e o Senhor o amou\". Deus não deixou esse amor implícito: \"enviou pela mão do profeta Natã, dando-lhe o nome de Jedidias, por amor ao Senhor\" (12:25) — Jedidias quer dizer \"amado do SENHOR\", e foi o próprio mensageiro do juízo quem veio trazer o nome de afeto. Este é o filho que edificaria a casa que o pai não pôde edificar, aquele de quem Deus dissera: \"Eu lhe serei por pai, e ele me será por filho\" (7:13-14). Berço nenhum da Escritura recebeu uma palavra assim tão cedo. Sobre um menino nascido logo depois do pior pecado do reino, a graça pôs a sua palavra primeiro." },
  benaia: { title: "Benaia", subtitle: "Filho de Joiada, sobre os quereteus e peleteus (2Sm 8:18; 23:20-23)", text: "De Cabzeel, filho de um homem valoroso e ele mesmo \"grande em obras\": feriu dois fortes heróis de Moabe e \"desceu ele, e feriu um leão no meio duma cova, no tempo da neve\" (23:20) — a Escritura guarda até o detalhe do tempo, porque descer a um poço gelado atrás de um leão é o retrato inteiro do homem. Enfrentou também um egípcio de respeito armado de lança levando apenas um cajado, \"e arrancou a lança da mão do egípcio, e com ela o matou\" (23:21). Nos anais dos valentes ficou registrado que \"teve nome entre três poderosos\", embora não chegasse aos três primeiros, e Davi o pôs sobre a sua guarda pessoal, os quereteus e os peleteus (23:22-23; 8:18). Nunca aparece do lado errado: não vacilou na fuga de Absalão, não entrou na conspiração de Adonias, e foi um dos três que Davi chamou para descer a Giom e ungir Salomão (1Rs 1:32-38). Foi ele quem executou as sentenças que fecharam a conta do reinado — Joabe agarrado às pontas do altar, e depois Simei (1Rs 2:34,46) — e recebeu o comando do exército (1Rs 2:35). O homem do leão na cova acabou general." },
  "adonias": {
    title: "Adonias",
    subtitle: "Filho de Hagite, o príncipe que se proclamou rei (1Rs 1:5)",
    text: "\"Então Adonias, filho de Hagite, se levantou, dizendo: Eu reinarei\" (1:5) — não foi ungido, não foi chamado, apenas se levantou. Imitou o irmão morto até nos detalhes: \"E preparou carros, e cavaleiros, e cinqüenta homens, que corressem adiante dele\" (1:5), exatamente como Absalão. E o versículo seguinte explica a vida inteira num aparte devastador: \"E nunca seu pai o tinha contrariado, dizendo: Por que fizeste assim? E era ele também muito formoso de parecer\" (1:6). Fez-se um banquete junto à pedra de Zoelete e convidou a todos, menos a Natã, a Benaia e a Salomão (1:9-10); mas o som das trombetas de Giom chegou ao meio da festa, e \"estremeceram e se levantaram todos os convidados\" (1:49). Correu ao santuário e \"apegou-se às pontas do altar\" (1:50), e Salomão o poupou com uma condição exata: \"Se for homem de bem, nem um de seus cabelos cairá em terra; se, porém, se achar nele maldade, morrerá\" (1:52). Não se achou homem de bem: voltou por Bate-Seba a pedir Abisague, começando com a frase que o entregou — \"Bem sabes que o reino era meu\" (2:15). Morreu naquele mesmo dia pela mão de Benaia (2:24-25). O filho que nunca ouviu um \"Por que fizeste assim?\" do pai acabou ouvindo do irmão a única palavra que ninguém adia.",
  },
  "salomao": {
    title: "Salomão",
    subtitle: "O rei sábio de Gibeom, o construtor do templo, o coração desviado (1Rs 1–11)",
    text: "Ungido em Giom sobre a mula do pai enquanto Adonias banqueteava (1:38-40), recebeu de Davi a ordem de partida: \"esforça-te, pois, e sê homem\" (2:2). Em Gibeom, Deus lhe abriu um cheque em branco — \"Pede o que queres que eu te dê\" (3:5) — e ele não pediu vida longa, nem riquezas, nem a morte dos inimigos: \"sou apenas um menino pequeno; não sei como sair, nem como entrar\" (3:7), \"dá um coração entendido para julgar a teu povo\" (3:9). Deus lhe deu o que pediu e o que não pediu: \"te dei um coração tão sábio e entendido, que antes de ti igual não houve, e depois de ti igual não se levantará\" (3:12). A espada pedida diante das duas prostitutas provou-o diante de Israel (3:24-28); \"disse três mil provérbios, e foram os seus cânticos mil e cinco\" (4:32), e sete anos de obra levantaram a casa do SENHOR, onde a nuvem entrou de tal modo que \"os sacerdotes não podiam permanecer em pé para ministrar\" (8:11). Ali orou a oração mais lúcida jamais feita por um construtor: \"Mas, na verdade, habitaria Deus na terra? Eis que os céus, e até o céu dos céus, não te poderiam conter, quanto menos esta casa que eu tenho edificado\" (8:27) — e nela pediu que Deus ouvisse também \"ao estrangeiro, que não for do teu povo Israel\" (8:41). E então a tragédia lenta: setecentas princesas e trezentas concubinas, e \"suas mulheres lhe perverteram o coração\" (11:3); altos a Quemós e a Moloque no monte diante de Jerusalém (11:7). O homem que orara pelo estrangeiro acabou adorando os deuses dele. \"certamente rasgarei de ti este reino, e o darei a teu servo\" (11:11): a sabedoria era dom, não blindagem.",
  },
  "roboao": {
    title: "Roboão",
    subtitle: "O filho de Salomão que partiu o reino em Siquém (1Rs 12)",
    text: "Foi a Siquém para ser feito rei e encontrou um povo com uma queixa concreta: \"Teu pai agravou o nosso jugo; agora, pois, alivia tu a dura servidão de teu pai\" (12:4). Pediu três dias e ouviu dois conselhos. Os anciãos lhe deram o retrato do reinado que salva: \"Se hoje fores servo deste povo, e o servires, e respondendo-lhe, lhe falares boas palavras, todos os dias serão teus servos\" (12:7). \"Porém ele deixou o conselho que os anciãos lhe tinham dado\" (12:8) e escolheu os que haviam crescido com ele, que lhe ensinaram a fanfarronice: \"Meu dedo mínimo é mais grosso do que os lombos de meu pai\" (12:10). No terceiro dia \"o rei respondeu ao povo duramente\" (12:13): \"meu pai vos castigou com açoites, porém eu vos castigarei com escorpiões\" (12:14). Dez tribos responderam com o grito que rasgou Israel em dois: \"Que parte temos nós com Davi?\" (12:16). Mandou Adorão, o da leva, e o viu ser apedrejado; escapou por pouco, \"o rei Roboão se animou a subir ao carro para fugir para Jerusalém\" (12:18). Ajuntou cento e oitenta mil homens para reconquistar o norte, e desistiu à palavra de Semaías (12:21-24). Reinou dezessete anos em Judá; sob ele o povo edificou altos e imagens de Aserá (14:23), Sisaque levou os tesouros do templo, e \"era o nome de sua mãe Naamá, amonita\" (14:21). \"porque esta revolta vinha do Senhor\" (12:15): a soberania de Deus não desculpou a estupidez do rei, apenas se serviu dela.",
  },
  "jeoiaquim": { title: "Jeoiaquim", subtitle: "Rei de Judá, o Eliaquim a quem Faraó mudou o nome (2Rs 23:34)", text: "Não foi escolhido por Deus nem pelo povo: Faraó Neco \"constituiu rei a Eliaquim, filho de Josias, em lugar de seu pai Josias\" e \"lhe mudou o nome para Jeoiaquim\" (2Rs 23:34). Para pagar o tributo, tributou os seus: \"a cada um segundo a sua avaliação exigiu a prata e o ouro do povo da terra\" (2Rs 23:35). Depois trocou de senhor: \"subiu Nabucodonosor, rei de babilônia, e Jeoiaquim ficou três anos seu servo; depois se virou, e se rebelou contra ele\" (2Rs 24:1), e vieram sobre Judá as tropas dos caldeus. Jeremias lhe prometeu sepultura de animal: \"Em sepultura de jumento será sepultado, sendo arrastado e lançado para bem longe, fora das portas de Jerusalém\" (Jr 22:19). Foi nos seus dias que começou o cativeiro (Dn 1:1-2)." },
  "pul-rei-da-assiria": { title: "Pul, rei da Assíria", subtitle: "O rei a quem Menaém comprou apoio com mil talentos de prata (2Rs 15:19)", text: "\"Então veio Pul, rei da Assíria, contra a terra; e Menaém deu a Pul mil talentos de prata, para que este o ajudasse a firmar o reino na sua mão\" (2Rs 15:19). Foi a primeira vez que a Assíria entrou nas contas de Israel, e entrou como sócia. O preço saiu do bolso do povo: \"de todos os poderosos e ricos\", \"de cada homem cinqüenta siclos de prata\" (2Rs 15:20). O império \"não ficou ali na terra\" (2Rs 15:20), mas não esqueceu o caminho: pouco depois Tiglate-Pileser levaria a Galiléia e Naftali (2Rs 15:29), e Samaria cairia (2Rs 17:6). Quem paga ao lobo para guardar a porta ensina-lhe o caminho de casa." },
  "jabez": { title: "Jabez", subtitle: "Mais ilustre do que seus irmãos (1Cr 4:9-10)", text: "No meio de nove capítulos de genealogia, dois versículos param a lista: \"E foi Jabez mais ilustre do que seus irmãos\" (1Cr 4:9). Carregava um nome que era uma ferida — a mãe lho deu \"dizendo: Porquanto com dores o dei à luz\" (1Cr 4:9) —, e foi contra esse nome que ele orou. \"Jabez invocou o Deus de Israel\", o Deus da aliança, e pediu quatro coisas: \"Se me abençoares muitíssimo, e meus termos ampliares, e a tua mão for comigo, e fizeres que do mal não seja afligido!\" (1Cr 4:10) — bênção, espaço, presença e guarda; nem vingança, nem grandeza para si. A resposta é a frase mais curta e mais alta do capítulo: \"E Deus lhe concedeu o que lhe tinha pedido\" (1Cr 4:10). Nada mais se sabe dele: nem pai, nem tribo, nem sepultura. Só que orou, e foi ouvido." },
  "mae-de-jabez": { title: "A mãe de Jabez", subtitle: "A que lhe deu um nome de dor (1Cr 4:9)", text: "Não tem nome na Escritura, mas é dela a única fala do trecho: \"sua mãe deu-lhe o nome de Jabez, dizendo: Porquanto com dores o dei à luz\" (1Cr 4:9). Em Israel o nome era destino, e ela pendurou no filho a memória do próprio sofrimento — como Raquel, que expirando no caminho de Efrata \"chamou-lhe Benoni\", enquanto o pai lhe punha nome de bênção (Gn 35:18). A dor de uma mãe abre esta história. Mas o filho levou o nome à oração, e \"Deus lhe concedeu o que lhe tinha pedido\" (1Cr 4:10): o que a dor nomeia, a graça pode reescrever." },
  "orna-jebuseu": { title: "Ornã, o jebuseu", subtitle: "O dono da eira onde a peste parou (1Cr 21:15-25)", text: "Cananeu remanescente em Jerusalém, dono de uma eira no alto do monte — e foi ali que a espada do anjo parou: \"E o anjo do Senhor estava junto à eira de Ornã, o jebuseu\" (1Cr 21:15). Estava trilhando o trigo quando se virou e viu o anjo, e os seus quatro filhos se esconderam (1Cr 21:20). Chegando Davi, prostrou-se com o rosto em terra e ofereceu tudo de graça: \"Toma-o para ti, e faça o rei meu senhor dele o que parecer bem aos seus olhos\", dando os bois para holocausto, os trilhos para lenha e o trigo para a oferta — \"tudo dou\" (1Cr 21:23). Davi recusou com a palavra que define a adoração verdadeira: \"não tomarei o que é teu, para o Senhor, para que não ofereça holocausto sem custo\" (1Cr 21:24), e pesou-lhe seiscentos siclos de ouro. Naquela eira desceu fogo do céu sobre o altar (1Cr 21:26), e ali Salomão edificaria a casa do SENHOR, \"no lugar que Davi tinha preparado na eira de Ornã, o jebuseu\" (2Cr 3:1)." },
  "amasai": { title: "Amasai", subtitle: "Chefe dos trinta, sobre quem veio o espírito (1Cr 12:18)", text: "Veio ter com Davi ao lugar forte à frente de homens de Benjamim e de Judá — isto é, com gente da própria tribo de Saul (1Cr 12:16). Davi saiu-lhes ao encontro com desconfiança justa, pedindo que, havendo traição, \"o Deus de nossos pais o veja e o repreenda\" (1Cr 12:17). A resposta não foi de homem: \"Então veio o espírito sobre Amasai, chefe de trinta, e disse: Nós somos teus, ó Davi, e contigo estamos, ó filho de Jessé!\" (1Cr 12:18). O juramento fecha-se numa tríplice paz que não se apoia na espada, e sim em Deus: \"Paz, paz contigo, e paz com quem te ajuda, pois que teu Deus te ajuda\" (1Cr 12:18). É a única boca destes capítulos por onde o Espírito irrompe, e o texto a nomeia. \"E Davi os recebeu, e os fez capitães das tropas\" (1Cr 12:18)." },
  "asafe-cantor": { title: "Asafe", subtitle: "Filho de Berequias, chefe dos cantores diante da arca (1Cr 15:17)", text: "Levita designado por Davi entre os três chefes do canto, \"Asafe, filho de Berequias\" (1Cr 15:17), constituído para o ofício \"depois que a arca teve repouso\" (1Cr 6:31). No coro fica ao lado direito de Hemã — \"E seu irmão Asafe estava à sua direita\" (1Cr 6:39) — e é o homem dos címbalos: \"os cantores, Hemã, Asafe e Etã, se faziam ouvir com címbalos de metal\" (1Cr 15:19). No dia em que a arca entrou na tenda, Davi lhe entregou o salmo para que, \"pelo ministério de Asafe e de seus irmãos, louvassem ao Senhor\" (1Cr 16:7), e ali o deixou \"para ministrarem continuamente perante a arca\" (1Cr 16:37). O Cronista chama o seu ofício de profecia: era ele \"que profetizava debaixo das ordens do rei Davi\" (1Cr 25:2). Doze salmos do saltério trazem o seu nome (Sl 50; 73—83): em Israel, o louvor tem autor e escala de serviço." },
  "nata-profeta": { title: "Natã", subtitle: "O profeta na corte de Davi (1Cr 17:1-15)", text: "Quando o rei lhe abriu o coração — \"Eis que moro em casa de cedro, mas a arca da aliança do SENHOR está debaixo de cortinas\" (1Cr 17:1) —, Natã respondeu do seu próprio juízo, e depressa: \"Tudo quanto tens no teu coração faze, porque Deus é contigo\" (1Cr 17:2). Mas \"na mesma noite, que a palavra de Deus veio a Natã\" (1Cr 17:3), e o profeta teve a humildade de voltar e desdizer-se: \"Tu não me edificarás uma casa para eu morar\" (1Cr 17:4). Em lugar da casa que Davi queria dar, Deus prometeu a casa que Ele faria — um filho, um trono e uma filiação: \"Eu lhe serei por pai, e ele me será por filho\" (1Cr 17:13), \"e o seu trono será firme para sempre\" (1Cr 17:14). É a aliança davídica, e ela vem por esta boca. Foi Natã também quem ungiu Salomão em Giom (1Rs 1:45), e os seus escritos guardaram os atos do rei: \"nas crônicas do profeta Natã\" (1Cr 29:29)." },
  "gade-vidente": { title: "Gade", subtitle: "O vidente de Davi (1Cr 21:9)", text: "\"Gade, o vidente de Davi\" (1Cr 21:9) acompanhava o rei desde os dias do desterro, quando lhe disse: \"Não fiques naquele lugar forte; vai, e entra na terra de Judá\" (1Sm 22:5). Depois do censo, coube-lhe levar a escolha impossível: \"Três coisas te proponho; escolhe uma delas\" — fome, espada ou peste — e trazer resposta: \"vê, pois, agora, que resposta hei de levar a quem me enviou\" (1Cr 21:12). O que Davi respondeu é uma das grandes confissões da Escritura: \"caia eu, pois, nas mãos do Senhor, porque são muitíssimas as suas misericórdias\" (1Cr 21:13). Detida a peste, foi ainda por Gade que veio a ordem de graça: \"o anjo do Senhor ordenou a Gade que dissesse a Davi para subir e levantar um altar ao Senhor na eira de Ornã, o jebuseu\" (1Cr 21:18). Com Samuel e Natã, deixou registro dos atos do rei — \"nas crônicas de Gade, o vidente\" (1Cr 29:29)." },
  "anjo-do-senhor-sobre-jerusalem": { title: "O anjo do SENHOR sobre Jerusalém", subtitle: "Entre a terra e o céu, com a espada estendida (1Cr 21:16)", text: "É a visão mais assombrosa das Crônicas: \"levantando Davi os seus olhos, viu o anjo do Senhor, que estava entre a terra e o céu, com a sua espada desembainhada na sua mão estendida contra Jerusalém\" (1Cr 21:16). Deus não é desenhado — o que se vê é o mensageiro enviado e a espada suspensa sobre uma cidade que ainda não tinha templo. Ao juízo em curso o próprio Deus pôs freio: \"disse ao anjo destruidor: Basta, agora retira a tua mão\" (1Cr 21:15). Diante da figura, \"Davi e os anciãos, cobertos de sacos, se prostraram sobre os seus rostos\" (1Cr 21:16), e o rei tomou sobre si a culpa do povo: \"estas ovelhas que fizeram?\" (1Cr 21:17). Erguido o altar na eira de Ornã e descido fogo do céu sobre o holocausto, veio o desfecho: \"E o Senhor deu ordem ao anjo, e ele tornou a sua espada à bainha\" (1Cr 21:27)." },
  "jeosafa": {
    title: "Jeosafá, rei de Judá",
    subtitle: "O filho de Asa que mandou ensinar a lei e pôs os cantores adiante do exército (2Cr 17—20)",
    text: "Reina vinte e cinco anos e é medido por um pastor, não por um palácio: \"E o Senhor era com Jeosafá; porque andou nos primeiros caminhos de Davi seu pai, e não buscou a Baalins\" (2Cr 17:3). No terceiro ano faz o que nenhum rei de Judá tinha feito — manda príncipes, levitas e sacerdotes ensinarem pelas cidades, \"levando consigo o livro da lei do Senhor\" (2Cr 17:9) — e o efeito é dissuasão, não conquista (2Cr 17:10). Erra duas vezes pelo mesmo motivo: \"aparentou-se com Acabe\" (2Cr 18:1) e quase morre em Ramote de Gileade, salvo por um grito (2Cr 18:31); e no fim alia-se com Acazias para fazer navios que se quebram em Eziom-Geber (2Cr 20:35-37). Repreendido à porta de casa por Jeú, filho de Hanani (2Cr 19:2), responde percorrendo o reino de Berseba a Efraim e pondo juízes de cidade em cidade, com a instrução que fez tribunal em Judá: \"não julgais da parte do homem, senão da parte do Senhor\" (2Cr 19:6). O ponto mais alto é a invasão de Moabe e Amom: teme, apregoa jejum, ora dizendo \"não sabemos o que faremos; porém os nossos olhos estão postos em ti\" (2Cr 20:12) e, ouvido Jaaziel, põe cantores \"saindo diante dos armados\" (2Cr 20:21). O veredicto do cronista: \"andou no caminho de Asa, seu pai, e não se desviou dele, fazendo o que era reto aos olhos do Senhor\" (2Cr 20:32) — com o mesmo limite do pai, porque \"os altos não foram tirados\" (2Cr 20:33).",
  },
  "maate-filho-de-amasai": {
    title: "Maate, filho de Amasai, dos filhos dos coatitas",
    subtitle: "2Cr 29:12 • o primeiro levita que se levantou quando o rei mandou limpar o templo",
    text: "\"Então se levantaram os levitas, Maate, filho de Amasai, e Joel, filho de Azarias, dos filhos dos coatitas\" (2Cr 29:12). O verbo é o do capítulo inteiro: levantaram-se. Ezequias tinha acabado de pregar na praça oriental que os pais \"desviaram os seus rostos do tabernáculo do Senhor, e lhe deram as costas\" (2Cr 29:6), e a resposta não foi discurso, foi trabalho braçal. Maate é coatita, da casa que no deserto carregava ao ombro as coisas mais santas — a arca, a mesa, o candeeiro, os altares (Nm 4:4-15) —, e o serviço que lhe cabe agora é o inverso e igualmente sagrado: tirar de dentro da casa a imundícia acumulada em dezesseis anos de portas fechadas. Ele e os outros treze \"ajuntaram a seus irmãos, e santificaram-se e vieram conforme ao mandado do rei, pelas palavras do Senhor, para purificarem a casa do Senhor\" (2Cr 29:15) — a ordem veio do rei, mas o texto faz questão de dizer de quem eram as palavras.",
  },
  "joa-filho-de-zima": {
    title: "Joá, filho de Zima, dos gersonitas",
    subtitle: "2Cr 29:12 • um dos dois gersonitas entre os catorze levitas da purificação",
    text: "\"e dos gersonitas, Joá, filho de Zima, e Éden, filho de Joá\" (2Cr 29:12) — pai e filho na mesma lista, os dois trabalhando na mesma faxina. Gérson é o primogênito de Levi, e a sua casa carregava no deserto as cortinas, as coberturas e o véu da porta do tabernáculo (Nm 3:25-26): os panos, tudo o que fecha e cobre. Em Crônicas os gersonitas aparecem ligados ao serviço do canto e dos tesouros (1Cr 23:7-11; 26:21-22). Joá reaparece no capítulo seguinte da história de Judá, num homônimo célebre: o \"Joá, filho de Asafe, o cronista\" que enfrentou Rabsaqué no muro (2Rs 18:18). O que este faz é menos vistoso e igualmente decisivo: está entre os que \"santificaram-se e vieram conforme ao mandado do rei, pelas palavras do Senhor\" (2Cr 29:15), no dia em que a casa de Deus foi reaberta.",
  },
  "hema-cantor": {
    title: "Hemã",
    subtitle: "Neto de Samuel, o vidente do rei nas palavras de Deus e chefe do canto ao centro do coro (1Cr 6:33; 25:5)",
    text: "É o cantor do meio, entre Asafe à direita e Etã à esquerda: \"Designaram, pois, os levitas a Hemã, filho de Joel; e dos seus irmãos, Asafe, filho de Berequias; e dos filhos de Merari, seus irmãos, Etã, filho de Cusaías\" (1Cr 15:17), e os três \"se faziam ouvir com címbalos de metal\" (1Cr 15:19). A sua genealogia é a mais espantosa do coro: \"dos filhos dos coatitas, Hemã, o cantor, filho de Joel, filho de Samuel\" (1Cr 6:33) — neto do profeta de Ramá, o mesmo Samuel que ungiu Saul e Davi. O ofício dele não é chamado música e sim profecia: Davi separou \"os filhos de Asafe, e de Hemã, e de Jedutum, para profetizarem com harpas, com címbalos, e com saltérios\" (1Cr 25:1), e o próprio Hemã é apresentado como \"o vidente do rei nas palavras de Deus, para exaltar o seu poder\" (1Cr 25:5). Teve catorze filhos e três filhas, todos sob a sua direção \"para a música da casa do Senhor\" (1Cr 25:5-6). Antes do templo servia diante da tenda, \"até que Salomão edificou a casa do Senhor em Jerusalém\" (1Cr 6:32); e no dia em que a casa ficou pronta está de linho fino ao oriente do altar, com Asafe e Jedutum, no coro que fez \"ouvir uma só voz\" (2Cr 5:12-13). O saltério guarda ainda o salmo mais escuro de todos debaixo do seu nome, o que começa \"SENHOR Deus da minha salvação, diante de ti tenho clamado de dia e de noite\" (Sl 88:1) e acaba sem consolo nenhum — o chefe do louvor de Israel também é o autor da sua oração mais desesperada.",
  },
  "jedutum-cantor": {
    title: "Jedutum",
    subtitle: "O terceiro chefe do canto, vidente do rei, cujos filhos ficavam à porta (1Cr 16:41-42; 2Cr 35:15)",
    text: "Aparece sempre em terceiro e nunca falta: \"E com eles a Hemã, e a Jedutum, e aos mais escolhidos, que foram apontados pelos seus nomes, para louvarem ao Senhor, porque a sua benignidade dura perpetuamente\" (1Cr 16:41). O detalhe que o distingue está no versículo seguinte, e é de escala de serviço: \"Com eles, pois, estavam Hemã e Jedutum, com trombetas e címbalos, para os que haviam de tocar, e com outros instrumentos de música de Deus; porém os filhos de Jedutum estavam à porta\" (1Cr 16:42) — a casa dele reparte-se entre o canto e a porteria, entre o coro e a soleira. O instrumento próprio dele é a harpa, e o ofício é chamado de profecia: \"Jedutum, o qual profetizava com a harpa, louvando e dando graças ao Senhor\" (1Cr 25:3). Como Hemã, recebe o título de vidente do rei (2Cr 35:15). No dia da dedicação está de linho fino ao oriente do altar, com os seus filhos e irmãos (2Cr 5:12). E a sua casa atravessa a história inteira do templo: filhos de Jedutum se santificam para limpar a casa no avivamento de Ezequias (2Cr 29:14), os cantores estão no posto \"segundo o mandado de Davi, e de Asafe, e de Hemã, e de Jedutum\" na páscoa de Josias (2Cr 35:15), e um descendente seu ainda mora em Jerusalém depois do exílio, no rol de Neemias (Ne 11:17). Três salmos do saltério trazem a indicação do seu nome (Sl 39; 62; 77): em Israel, até o modo de cantar tinha titular.",
  },
  "abias-rei-de-juda": {
    title: "Abias, rei de Judá",
    subtitle: "2Cr 13 — o rei que pregou em cima do monte de Zemaraim ao exército inimigo",
    text: "Reinou três anos e ficou na Escritura por um discurso. Filho de Roboão e de Maaca, foi escolhido herdeiro por preferência do pai — \"Roboão designou Abias, filho de Maaca, para ser chefe e líder entre os seus irmãos, porque queria fazê-lo rei\" (2Cr 11:22) — e herdou uma guerra: \"e houve guerra entre Abias e Jeroboão\" (2Cr 13:2). Com quatrocentos mil homens contra oitocentos mil, fez o que nenhum outro rei fez: \"E pôs-se Abias em pé em cima do monte de Zemaraim, que está na montanha de Efraim, e disse: Ouvi-me, Jeroboão e todo o Israel\" (2Cr 13:4). O argumento é inteiramente teológico — o direito perpétuo de Davi \"por uma aliança de sal\" (2Cr 13:5); a acusação de que Jeroboão era \"servo de Salomão\" rebelado contra o seu senhor (2Cr 13:6); os bezerros de ouro feitos para deuses (2Cr 13:8); o sacerdócio que se compra \"com um novilho e sete carneiros\" (2Cr 13:9); e, do outro lado, o serviço que não parou, com \"os pães da proposição sobre a mesa pura, e o castiçal de ouro\" (2Cr 13:11). Termina gritando do alto: \"E eis que Deus está conosco, à nossa frente\" (2Cr 13:12). Jeroboão respondeu com emboscada pela retaguarda; Judá, cercado por diante e por detrás, \"clamaram ao Senhor; e os sacerdotes tocaram as trombetas\" (2Cr 13:14), e o desfecho não é dele: \"Deus feriu a Jeroboão e a todo o Israel diante de Abias e de Judá\" (2Cr 13:15). Tomou Betel, Jesana e Efrom, fortificou-se, tomou catorze mulheres, e morreu com três anos de reinado. 1 Reis dá dele um veredicto duro (1Rs 15:3); 2 Crônicas guarda o sermão inteiro, escrito \"na história do profeta Ido\" (2Cr 13:22).",
  },
  "manasses-rei-de-juda": {
    title: "Manassés, rei de Judá",
    subtitle: "Filho de Ezequias, doze anos de idade e cinquenta e cinco de reinado (2Cr 33:1)",
    text: "O reinado mais longo da casa de Davi e o pior: \"Tinha Manassés doze anos de idade, quando começou a reinar, e cinqüenta e cinco anos reinou em Jerusalém\" (2Cr 33:1) — filho de Hefzibá (2Rs 21:1) e do rei que tinha aberto as portas do templo, desfez tudo o que o pai fizera. Reedificou os altos derrubados, levantou altares aos Baalins, prostrou-se diante de todo o exército dos céus, encheu de altares \"ambos os átrios da casa do Senhor\" (2Cr 33:5), fez passar os filhos pelo fogo no vale do filho de Hinom, consultou adivinhos e encantadores e pôs uma imagem de escultura dentro da casa de que Deus dissera \"porei o meu nome para sempre\" (2Cr 33:7). Reis acrescenta o que Crônicas cala: \"também Manassés derramou muitíssimo sangue inocente, até que encheu a Jerusalém de um ao outro extremo\" (2Rs 21:16). Deus falou por videntes e ele não deu ouvidos (2Cr 33:10). Então veio a Assíria: \"os quais prenderam a Manassés com ganchos e, amarrando-o com cadeias, o levaram para Babilônia\" (2Cr 33:11). E ali, no fundo, aconteceu o que faz deste o capítulo mais estranho de Judá: \"E ele, angustiado, orou deveras ao Senhor seu Deus, e humilhou-se muito perante o Deus de seus pais… e Deus se aplacou para com ele, e ouviu a sua súplica, e tornou a trazê-lo a Jerusalém, ao seu reino. Então conheceu Manassés que o Senhor era Deus\" (2Cr 33:12-13). Voltou, levantou o muro de fora muito alto, tirou da casa os deuses estranhos e o ídolo e reparou o altar (2Cr 33:14-16). Foi sepultado em sua própria casa, não nos sepulcros dos reis (2Cr 33:20); o pecado dele, porém, é o que Reis dá como causa final do exílio (2Rs 24:3-4).",
  },
  "fineias-filho-de-eleazar": {
    title: "Finéias, filho de Eleazar, o que deteve a praga em Sitim",
    subtitle: "Ed 7:5 • Nm 25:7-13 — o degrau em que a genealogia de Esdras encosta no deserto",
    text: "\"Filho de Abisua, filho de Finéias, filho de Eleazar, filho de Arão, o sumo sacerdote\" (Ed 7:5). Quando Israel se prostituiu com as filhas de Moabe em Sitim e um homem trouxe uma midianita à vista de toda a congregação que chorava à porta da tenda, Finéias levantou-se do meio do povo com uma lança na mão e a praga parou: \"então a praga cessou de sobre os filhos de Israel\" (Nm 25:8). A palavra que veio a seguir é a razão de este nome estar em Esdras 7: \"Portanto dize: Eis que lhe dou a minha aliança de paz\" (Nm 25:12), e por ela lhe foi dada \"a aliança do sacerdócio perpétuo\" (Nm 25:13). Ele reaparece guardando a arca em Betel (Jz 20:28) e enviado às tribos do outro lado do Jordão por causa do altar de Ede (Js 22:13,30-31). O caso de Sitim é exatamente o pecado de Esdras 9: casamento com os povos da terra — e o descendente de Finéias, quatro capítulos adiante, não pega lança nenhuma: senta-se no chão e chora.",
  },
  "eleazar-filho-de-arao": {
    title: "Eleazar, filho de Arão, que recebeu as vestes do pai no monte Hor",
    subtitle: "Ed 7:5 • Nm 20:25-28 — o penúltimo degrau da genealogia de Esdras",
    text: "Terceiro filho de Arão, e sumo sacerdote depois da morte de Nadabe e Abiú, que ofereceram fogo estranho (Lv 10:1-2). A sua investidura foi feita numa montanha, diante de todo o povo: \"E despe a Arão as suas vestes, e veste-as em Eleazar, seu filho, porque Arão será recolhido, e morrerá ali\" (Nm 20:26). Foi ele quem, com Josué, repartiu a terra por sortes em Siló (Js 14:1; 19:51), e quem devia consultar por Urim diante do SENHOR quando se tratasse de sair ou entrar (Nm 27:21). Está sepultado no outeiro de Finéias, seu filho, no monte de Efraim (Js 24:33). É por esta linha — e não pela de Itamar — que a genealogia de Esdras sobe, e é aqui que ela quase chega ao fim: falta um nome só.",
  },
};
